import json, numpy as np, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
L = json.load(open('lens347.json')); pm = {float(k): v['deg'] + (v['dir_up'] - v['dir_dn']) for k, v in L.items()}; pm[0.0] = abs(L['0.0']['dir_up'] - L['0.0']['dir_dn'])
D = {d: json.load(open(f'drop347_d{d}.json')) for d in (20, 40, 60)}
fig, ax = plt.subplots(1, 3, figsize=(16, 5.2), gridspec_kw=dict(width_ratios=[1.1, 0.9, 0.85]))
d = np.load('drop347_d40.npz'); Q, s, P, delta, u = d['Q'], d['snap'], d['P'], d['delta'], d['u']; m = np.isfinite(Q[:, 0]) & (np.hypot(*Q.T) < 88)
a = ax[0]; a.scatter(Q[m, 0], Q[m, 1], c=s[m], s=1.0, cmap='RdBu_r', vmin=-0.6, vmax=0.6, rasterized=True)
for sg in (1, -1): a.plot([25*np.cos(np.radians(20)), 88*np.cos(np.radians(20))], [sg*25*np.sin(np.radians(20)), sg*88*np.sin(np.radians(20))], 'k--', lw=0.8)
a.add_patch(plt.Circle((0, 0), 25, color='#f2c94c', alpha=0.5)); a.text(0, 0, 'крапля світу\n(криву частину\nне розгорнуто)', ha='center', va='center', fontsize=8)
a.text(62, 0, 'виріз 40°\n(краї склеєні)', ha='center', va='center', fontsize=8)
a.set_aspect('equal'); a.set_xlim(-90, 90); a.set_ylim(-90, 90); a.set_xticks([]); a.set_yticks([])
a.set_title('а) хвиля повз краплю (Σδ = 40°), t = 100:\nзовнішня Матриця пласка, але з вирізом — два фронти позаду', fontsize=10)
a = ax[1]; r = np.hypot(*P.T); o = np.argsort(r); inner = delta > 0
a.plot(r[inner], np.degrees(delta[inner])*1000, '.', ms=2, color='#d9480f', label='дефіцит кута у вузлі δ_v, ×10⁻³ °')
a2 = a.twinx(); a2.plot(r[o], u[o], '-', color='#2a6fdb', lw=1); a2.set_ylabel('масштаб ниток u (довжина ∝ e^u)', color='#2a6fdb')
a.set_xlim(0, 60); a.set_xlabel('відстань від центру краплі (вузли)'); a.set_ylabel('δ_v, ×10⁻³ °', color='#d9480f')
a.axvline(15, color='k', lw=0.6, ls=':'); a.text(15.5, a.get_ylim()[1]*0.9, 'стінка', fontsize=8)
a.set_title('б) енергія стінки гне простір лише там, де вона є:\nусередині й зовні вузли пласкі', fontsize=10)
a = ax[2]; xs = np.array([0, 20, 40, 60])
a.plot([0, 65], [0, 65], 'k-', lw=0.8, label='2D-ЗТВ: кут = 8πG·E')
a.plot(xs, [pm[float(x)] for x in xs], 'o', color='#d9480f', label='точкова маса (один вузол)')
a.plot([20, 40, 60], [D[x]['lens'] for x in (20, 40, 60)], 's', color='#2a6fdb', label='крапля світу r₀ = 15 (стінка)')
a.plot([60], [58.2], 'x', color='#555555', ms=8, label='(344) дисклінація (лише 60°)')
a.set_xlabel('8πG·E = повний дефіцит кута, °'); a.set_ylabel('кут лінзи з хвилі, °'); a.legend(fontsize=8, loc='upper left'); a.set_xlim(-3, 66); a.set_ylim(-3, 66)
a.set_title('в) лінза ∝ енергії, будь-якої величини', fontsize=10)
plt.tight_layout(); plt.savefig('/mnt/project-files/figures/fig242_gravity_postulate.png', dpi=120)
print(pm, {x: D[x]['lens'] for x in D})
